import{_ as i,o as a,c as e,aO as s}from"./chunks/framework.vjUPZZJn.js";const k=JSON.parse('{"title":"CLI11 add_option 两种用法与多值策略","description":"","frontmatter":{"date":"2026-11-18T11:00:00.000Z","title":"CLI11 add_option 两种用法与多值策略","source":[[["1-知识/C++/CLI11——add_option函数"]]],"tags":["编程语言","C++","CLI11","命令行解析"],"categories":["计算机"],"permalink":"/pages/95b6e9"},"headers":[],"relativePath":"计算机/CLI11 add_option 两种用法与多值策略.md","filePath":"计算机/CLI11 add_option 两种用法与多值策略.md","lastUpdated":1794967269000}'),d={name:"计算机/CLI11 add_option 两种用法与多值策略.md"};function o(l,t,n,p,r,h){return a(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="cli11-add-option-两种用法与多值策略" tabindex="-1">CLI11 add_option 两种用法与多值策略 <a class="header-anchor" href="#cli11-add-option-两种用法与多值策略" aria-label="Permalink to &quot;CLI11 add_option 两种用法与多值策略&quot;">​</a></h1> <p>CLI11 是一个 header-only 的现代 C++ 命令行解析库，<code>add_option</code> 是使用频率最高的入口。它的调用形态主要有两类：直接绑定变量，或保存返回的 <code>CLI::Option*</code> 再做配置。两类写法各自适合什么场景、多值选项为什么必须显式配置策略，本文结合库源码把这些区别说清楚。</p> <h2 id="方式一-直接绑定变量" tabindex="-1">方式一：直接绑定变量 <a class="header-anchor" href="#方式一-直接绑定变量" aria-label="Permalink to &quot;方式一：直接绑定变量&quot;">​</a></h2> <div class="language-cpp vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::string output;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">add_option</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-o, --output&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, output, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Specify the output file&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>用户输入 <code>-o file.txt</code> 并通过解析后，<code>output</code> 的值就是 <code>&quot;file.txt&quot;</code>。这种写法的特点：</p> <ul><li>值直接存储到绑定的变量中，不需要处理返回值；</li> <li>适合只需要一个值的选项；</li> <li>绑定到 <code>std::vector&lt;std::string&gt;</code> 等容器时，CLI11 会自动放开数量上限，把多次传入的值全部收集进容器——多值场景并不要求保存 <code>Option*</code>，绑定 vector 就够了。</li></ul> <h2 id="方式二-保存返回值并配置策略" tabindex="-1">方式二：保存返回值并配置策略 <a class="header-anchor" href="#方式二-保存返回值并配置策略" aria-label="Permalink to &quot;方式二：保存返回值并配置策略&quot;">​</a></h2> <div class="language-cpp vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CLI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::Option</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> linkDirsOpt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">linkDirsOpt </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">add_option</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-L, --link-dir&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Specify one directory where to link modules&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">                  -&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">multi_option_policy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CLI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MultiOptionPolicy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::TakeAll);</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>add_option</code> 返回 <code>CLI::Option*</code>，保存它可以在解析前后对选项做进一步配置：多值策略、检查器（<code>check()</code>）、回调（<code>each()</code>）等。用户输入 <code>-L dir1 -L dir2</code> 后，通过 <code>linkDirsOpt-&gt;results()</code> 可以取得所有值（<code>{&quot;dir1&quot;, &quot;dir2&quot;}</code>）。</p> <p>这种写法不绑定变量，值的获取完全经由选项对象，适合需要额外配置或解析后再统一取值的场景。</p> <h2 id="默认策略是-throw-显式-takeall-不可省" tabindex="-1">默认策略是 Throw，显式 TakeAll 不可省 <a class="header-anchor" href="#默认策略是-throw-显式-takeall-不可省" aria-label="Permalink to &quot;默认策略是 Throw，显式 TakeAll 不可省&quot;">​</a></h2> <p>一个容易踩的点：CLI11 的默认多值策略是 <code>MultiOptionPolicy::Throw</code>（<code>Option.hpp</code> 中 <code>multi_option_policy_{MultiOptionPolicy::Throw}</code>）。</p> <p>对不绑定变量的选项，数量上限默认为 1。此时重复传参（<code>-L dir1 -L dir2</code>）不会安静地收集两个值，而是直接抛出 <code>ArgumentMismatch::AtMost</code> 异常。所以上面的方式二里，<code>multi_option_policy(CLI::MultiOptionPolicy::TakeAll)</code> 是必要的配置，不是可有可无的装饰。</p> <p>各策略的语义（<code>Option.hpp</code> 枚举注释）：</p> <table tabindex="0"><thead><tr><th>策略</th> <th>行为</th></tr></thead> <tbody><tr><td><code>Throw</code></td> <td>超出预期数量即抛错（默认）</td></tr> <tr><td><code>TakeAll</code></td> <td>收集全部传入值</td></tr> <tr><td><code>TakeLast</code> / <code>TakeFirst</code></td> <td>只取最后 / 最前 N 个</td></tr> <tr><td><code>Join</code></td> <td>合并成单个字符串（默认 <code>\\n</code> 分隔）</td></tr> <tr><td><code>Sum</code></td> <td>数值求和或字符串直接拼接</td></tr> <tr><td><code>Reverse</code></td> <td>取最后 N 个并反转顺序</td></tr></tbody></table> <h2 id="两种方式对比" tabindex="-1">两种方式对比 <a class="header-anchor" href="#两种方式对比" aria-label="Permalink to &quot;两种方式对比&quot;">​</a></h2> <table tabindex="0"><thead><tr><th>特性</th> <th>直接绑定变量</th> <th>保存返回值配置策略</th></tr></thead> <tbody><tr><td>值的获取</td> <td>自动写入绑定变量</td> <td>经 <code>Option*</code> 的 <code>results()</code> 等</td></tr> <tr><td>多值支持</td> <td>绑定标量时单值；绑定 <code>std::vector&lt;T&gt;</code> 时自动收集全部</td> <td>经 <code>multi_option_policy</code> 配置</td></tr> <tr><td>返回值处理</td> <td>通常忽略</td> <td>保存 <code>CLI::Option*</code> 进一步配置</td></tr> <tr><td>适用场景</td> <td>简单单值选项</td> <td>多值或需要检查器、回调等附加配置</td></tr></tbody></table> <p>两种方式并不互斥：可以既绑定变量又保存返回值，在自动接收值的同时对选项做进一步配置。</p> <h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2> <ul><li>单值选项直接绑定变量，多值选项绑定 <code>std::vector&lt;T&gt;</code> 是最省事的写法；</li> <li>默认多值策略是 <code>Throw</code>，不绑定变量而想接受重复传参时，必须显式设置 <code>TakeAll</code>，否则解析阶段抛 <code>ArgumentMismatch</code>；</li> <li>需要检查器、回调等附加配置时保存 <code>Option*</code>，它与变量绑定可以同时使用。</li></ul>`,37)])])}const u=i(d,[["render",o]]);export{k as __pageData,u as default};
